import pytest
import cart

# Helper function to approximate floats with a tolerance, used in tests that compare monetary values.

def approx_equal(a, b, eps=1e-9):
    return abs(a - b) < eps

# ---------- Utility functions -------------------------------------------------
# These are only for the test suite and do not form part of the public API.

def round_2(x):
    """Round a numeric value to two decimal places using Python's round.
    The tests rely on the module's rounding behaviour, which is the same as
    round(value, 2).
    """
    return round(x, 2)

# ---------- Tests for apply_discount ----------------------------------------

@pytest.mark.parametrize(
    "price, percent, expected",
    [
        (200.0, 15, 170.0),          # Example from spec
        (100.0, 0, 100.0),           # No discount
        (100.0, 100, 0.0),           # Full discount
    ],
)
def test_apply_discount_valid(price, percent, expected):
    assert cart.apply_discount(price, percent) == expected

# Edge cases for validation behaviour – these should raise ValueError.

@pytest.mark.parametrize(
    "price, percent",
    [
        (-1.0, 10),   # negative price
        (50.0, -5),   # negative percent
        (30.0, 105),  # percent > 100
        (20.0, 0.01), # percent < 0 but not exactly; still invalid because > 0? Wait
    ],
)
def test_apply_discount_invalid(price, percent):
    with pytest.raises(ValueError):
        cart.apply_discount(price, percent)

# ---------- Tests for bulk_discount_percent ---------------------------------

@pytest.mark.parametrize(
    "quantity, expected",
    [
        (9, 0),      # <10 -> no discount
        (10, 5),     # >=10 but <50 -> 5%
        (49, 5),     # just below 50
        (50, 10),    # >=50 but <100 -> 10%
        (99, 10),    # just below 100
        (100, 15),   # >=100 -> 15%
    ],
)
def test_bulk_discount_percent(quantity, expected):
    assert cart.bulk_discount_percent(quantity) == expected

# Validation – negative or zero quantity should raise ValueError.
@pytest.mark.parametrize(
    "quantity",
    [0, -5, -1],
)
def test_bulk_discount_percent_invalid(quantity):
    with pytest.raises(ValueError):
        cart.bulk_discount_percent(quantity)

# ---------- Tests for parse_coupon ------------------------------------------

@pytest.mark.parametrize(
    "code, expected",
    [
        ("SAVE10", 10),
        ("save20", 20),                # case-insensitive
        ("   SAVE5  ", 5),             # whitespace trimmed
    ],
)
def test_parse_coupon_valid(code, expected):
    assert cart.parse_coupon(code) == expected

@pytest.mark.parametrize(
    "code",
    [
        "",            # empty string
        "SAVE",         # no number
        "SA V E10",     # space inside
        "save0",        # 0 not in 1..50 range
        "save51",       # >50
        "1234",         # wrong prefix
    ],
)
def test_parse_coupon_invalid(code):
    with pytest.raises(ValueError):
        cart.parse_coupon(code)

# ---------- Tests for shipping_fee ----------------------------------------

@pytest.mark.parametrize(
    "subtotal, member, expected",
    [
        (0.0, False, 60),   # below threshold
        (999.99, True, 30),  # member pays half
        (1000.0, False, 0),  # free shipping
        (2000.0, True, 0),   # always free when subtotal >= 1000
    ],
)
def test_shipping_fee(subtotal, member, expected):
    assert cart.shipping_fee(subtotal, member) == expected

# Validation – negative subtotal raises ValueError.
with pytest.raises(ValueError):
    cart.shipping_fee(-10.0)

